INSERT INTO "person" ("id","first_name","last_name","tax_id","email","phone","notes","created_at","updated_at","birth_date","birth_place","birth_country","gender","profession","member_number") VALUES('adf27177-7d12-4d4f-91bd-22a7f6199d71','Ilaria','Filetti',NULL,NULL,'3452962979',replace('a quanto pare è inesistente dappertutto,\nmancanza di data entrata e uscita,\nsicuramente socia perché è stata eletta come tesoriere,\nsenza data uscita, è stata inventata come un mese dopo il termine del mandato,\ndata entrata messa come un se mesi prima dell''elezione,','\n',char(10)),'2026-03-15 13:40:04','2026-03-16T22:30:47.855Z','2000-01-26',NULL,NULL,'F','Studente','(-) Polito');
